**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <cmath>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("punkty.txt");
    int n;
    plik >> n;
    vector<int> X(n), Y(n);
    for (int i = 0; i < n; i++) plik >> X[i] >> Y[i];

    double minD = 1e18, maxD = -1;
    int minI = 0, minJ = 1, maxI = 0, maxJ = 1;
    int calkowite = 0;

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int dx = X[j] - X[i];
            int dy = Y[j] - Y[i];
            int dist2 = dx * dx + dy * dy;
            double d = sqrt((double)dist2);
            if (d < minD) { minD = d; minI = i; minJ = j; }
            if (d > maxD) { maxD = d; maxI = i; maxJ = j; }
            int rd = (int)round(d);
            if (rd * rd == dist2) calkowite++;
        }
    }

    cout << fixed << setprecision(2);
    cout << "a) Najblizsze: (" << X[minI] << "," << Y[minI] << ") i ("
         << X[minJ] << "," << Y[minJ] << "), odleglosc = " << minD << endl;
    cout << "b) Najdalsze: (" << X[maxI] << "," << Y[maxI] << ") i ("
         << X[maxJ] << "," << Y[maxJ] << "), odleglosc = " << maxD << endl;
    cout << "c) Pary z calkowita odlegloscia: " << calkowite << endl;
    return 0;
}
```

**Wyjasnienie**: Podwojna petla sprawdza wszystkie C(n,2)=10 par. Dla kazdej pary liczymy odleglosc i sledzimy minimum/maximum. Calkowita odleglosc sprawdzamy testujac czy dx^2+dy^2 jest kwadratem doskonalym.

